<?php
declare(strict_types=1);
require dirname(__DIR__) . '/lib_indices.php';
require dirname(__DIR__) . '/lib_exercicios.php';
$dsn = getenv('KRIEGER_TEST_DSN') ?: '';
if ($dsn !== 'mysql:host=127.0.0.1;port=3306;dbname=krieger_test;charset=utf8mb4') throw new RuntimeException('Use apenas o banco efêmero do CI.');
$pdo = new PDO($dsn, 'root', getenv('KRIEGER_TEST_PASSWORD') ?: '', [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
foreach (['condominios','exercicios','mensais','config'] as $t) $pdo->exec("CREATE TABLE IF NOT EXISTS kr_$t (id VARCHAR(64) PRIMARY KEY, dados LONGTEXT NOT NULL, atualizado_em DATETIME NOT NULL) ENGINE=InnoDB");
$pdo->exec('CREATE TABLE kr_indices_condominio (id VARCHAR(64) PRIMARY KEY, condo_id VARCHAR(64) NOT NULL, ano INT NOT NULL, indice DECIMAL(10,4) NOT NULL, tipo VARCHAR(50), mes_referencia INT, data_aplicacao DATETIME NOT NULL, INDEX idx_condo_ano(condo_id,ano)) ENGINE=InnoDB');
$assert = static function(bool $ok, string $msg): void { if (!$ok) throw new RuntimeException($msg); };
$falha = static function(callable $fn) use ($assert): void { try { $fn(); } catch (RuntimeException|InvalidArgumentException $e) { return; } $assert(false, 'Operação deveria ter sido bloqueada.'); };
$c = ['id'=>'teste-indices-c', 'nome'=>'Condomínio fictício', 'unidades'=>10, 'indices'=>[]];
$e = ['id'=>'teste-fechar-e', 'condoId'=>$c['id'], 'ano'=>2026, 'demonstrativo'=>['periodo'=>['ini'=>'01/01/2026','fim'=>'31/12/2026']], 'consid'=>['indices'=>[['ano'=>2024,'pct'=>4.5],['ano'=>2025,'pct'=>6]]]];
gravar_registro_exercicio($pdo, 'condominios', $c);
$pdo->beginTransaction(); inicializar_indices_importados($pdo, $e); $pdo->commit();
$assert((int)$pdo->query("SELECT COUNT(*) FROM kr_indices_condominio WHERE condo_id='teste-indices-c'")->fetchColumn()===2, 'Primeira importação não alimentou a tabela.');
$c = ler_registro_exercicio($pdo, 'condominios', $c['id']);
$assert(count(incluir_indices_tabela($pdo,$c)['indices'])===2, 'Cadastro não lê índices da tabela.');
$pdo->beginTransaction(); $c['indices']=[['ano'=>2025,'pct'=>7,'noRelatorio'=>false]]; $c=substituir_indices_condominio($pdo,$c); gravar_registro_exercicio($pdo,'condominios',$c); $pdo->commit();
$assert(incluir_indices_tabela($pdo,$c)['indices'][0]['pct']===7.0, 'Edição do cadastro não persistiu.');
$assert(incluir_indices_tabela($pdo,$c)['indices'][0]['noRelatorio']===false, 'Preferência de impressão perdida.');
$pdo->beginTransaction(); $c['indices']=[]; $c=substituir_indices_condominio($pdo,$c); gravar_registro_exercicio($pdo,'condominios',$c); inicializar_indices_importados($pdo,$e); $pdo->commit();
$assert(count(incluir_indices_tabela($pdo,$c)['indices'])===0, 'Reimportação ressuscitou índice excluído.');
$falha(fn()=>validar_indices_condominio([['ano'=>2025,'pct'=>3],['ano'=>2025,'pct'=>5]]));
$falha(fn()=>validar_indices_condominio([['ano'=>2025,'pct'=>null]]));
$pdo->beginTransaction(); $c['indices']=[['ano'=>2025,'pct'=>8]]; substituir_indices_condominio($pdo,$c); $pdo->rollBack();
$assert((int)$pdo->query("SELECT COUNT(*) FROM kr_indices_condominio WHERE condo_id='teste-indices-c'")->fetchColumn()===0, 'Rollback deixou índices parciais.');
$e=gravar_registro_exercicio($pdo,'exercicios',$e);
$fechado=alterar_fechamento_exercicio($pdo,$e['id'],true,['id'=>'usuario-comum','perfil'=>'user'],'',$e['atualizadoEm']);
$assert($fechado['fechado'] && $fechado['fechamento']['condominio']['unidades']===10, 'Fechamento sem snapshot.');
$assert($fechado['fechamento']['fechadoPor']==='usuario-comum', 'Fechamento exigiu admin.');
$falha(fn()=>validar_edicao_exercicio($fechado,array_merge($fechado,['fechado'=>false])));
$falha(fn()=>validar_edicao_exercicio(null,['fechado'=>true]));
$falha(fn()=>exigir_exercicios_abertos($pdo,$c['id']));
$falha(fn()=>alterar_fechamento_exercicio($pdo,$e['id'],false,['id'=>'usuario-comum'],'',$fechado['atualizadoEm']));
$aberto=alterar_fechamento_exercicio($pdo,$e['id'],false,['id'=>'usuario-comum'],'Correção conferida',$fechado['atualizadoEm']);
$assert(!$aberto['fechado'] && !isset($aberto['fechamento']) && count($aberto['historicoFechamento'])===2, 'Reabertura não auditada.');
$assert($aberto['historicoFechamento'][1]['motivo']==='Correção conferida', 'Motivo perdido.');
$falha(fn()=>alterar_fechamento_exercicio($pdo,$e['id'],true,['id'=>'usuario-comum'],'','versao-obsoleta'));
echo "Índices e fechamento: importação, cadastro, exclusão, rollback, snapshot, bloqueio e reabertura validados.\n";
